-- PT107-S3-Q7. Approved 2026-10-01.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT107-S3-Q7$batch02$ AND q.stimulus=$batch02$Newsletter for community-center volunteers: Retired persons who regularly volunteer their time to help others generally display fewer and milder effects of aging than their nonvolunteering contemporaries: in social resources, mental outlook, physical health, economic resources, and overall functioning, they are found to be substantially stronger than nonvolunteers. Volunteering is often described as doing good works to improve the lives of others. How good to know that there is evidence that it can equally benefit your own well-being!$batch02$ AND q.prompt=$batch02$The inference drawn above is unwarranted because$batch02$ AND q.correct_choice=$batch02$E$batch02$) THEN RAISE EXCEPTION 'Question changed: PT107-S3-Q7'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch02$fe385aad-5e4a-42ce-9d3c-df4b09ac8162$batch02$) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch02$fe385aad-5e4a-42ce-9d3c-df4b09ac8162$batch02$) <> 4 THEN RAISE EXCEPTION 'Explanation changed: PT107-S3-Q7'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$C$batch02$, $batch02$This tries the "groups not fair to compare" objection, so test it. The volunteers are compared with their *contemporaries*, people of roughly the same age. A few nonvolunteers being somewhat older than a few volunteers would not explain gaps in money, social resources and outlook across the whole group. The comparison is fair enough on age. The real problem is the direction of cause, which is what (E) supplies.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT107-S3-Q7$batch02$ AND e.id=$batch02$fe385aad-5e4a-42ce-9d3c-df4b09ac8162$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
